function serializeFacets(rows) {
  assertDenseArray(rows);

  const pairs = [];

  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];

    if (row === null || typeof row !== "object") {
      throw new TypeError();
    }

    const prototype = Object.getPrototypeOf(row);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new TypeError();
    }

    if (typeof row.name !== "string") {
      throw new TypeError();
    }

    assertDenseArray(row.values);

    const encodedName = encodeRFC3986(row.name);

    for (let j = 0; j < row.values.length; j += 1) {
      const value = row.values[j];

      if (typeof value !== "string") {
        throw new TypeError();
      }

      pairs.push([encodedName, encodeRFC3986(value)]);
    }
  }

  pairs.sort(function (left, right) {
    if (left[0] < right[0]) return -1;
    if (left[0] > right[0]) return 1;
    if (left[1] < right[1]) return -1;
    if (left[1] > right[1]) return 1;
    return 0;
  });

  return pairs.map(function (pair) {
    return pair[0] + "=" + pair[1];
  }).join("&");
}

function assertDenseArray(value) {
  if (!Array.isArray(value)) {
    throw new TypeError();
  }

  for (let i = 0; i < value.length; i += 1) {
    if (!Object.prototype.hasOwnProperty.call(value, i)) {
      throw new TypeError();
    }
  }
}

function encodeRFC3986(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, function (character) {
    return "%" + character.charCodeAt(0).toString(16).toUpperCase();
  });
}
